with rr as (select s.id as src, (e ->> 'to')::uuid as tgt, e ->> 'assign' as role from wf_spaces s, jsonb_array_elements(coalesce(s.rules, '[]'::jsonb)) e where coalesce(e ->> 'assign', '') != '' and coalesce(e ->> 'to', '') ~* '^[0-9a-f-]{36}$'), c as (select b.id, b.num, rr.role, (select t from wf_teams t where t.division_id = b.division_id and t.id::text in (select value from jsonb_each_text(coalesce(b.fields, '{}'::jsonb))) order by t.name limit 1) as team from wf_bids b join rr on b.space_id = rr.tgt join wf_bids o on o.id = b.origin_bid_id and o.space_id = rr.src), cand as (select c.id, c.num, c.role, (c.team).id as team_id, (c.team).name as team_name, array(select x.id::text from wf_people x where x.id::text in (select jsonb_array_elements_text(coalesce((c.team).members, '[]'::jsonb))) and lower(coalesce(x.role, '')) = lower(c.role) order by x.name, x.id) as cands from c), q as (select cand.*, case when coalesce(array_length(cands, 1), 0) > 0 then cands[((row_number() over (partition by team_id, lower(role) order by num, id) - 1) % array_length(cands, 1))::int + 1] end as pid from cand), q2 as (select q.*, (select x.name from wf_people x where x.id::text = q.pid) as pname, (extract(epoch from now()) * 1000)::bigint as ms from q), upd as (update wf_bids b set assignee = q2.pid, reporter = coalesce(q2.pid, ''), history = coalesce(b.history, '[]'::jsonb) || (case when coalesce(q2.pid, '') is distinct from coalesce(b.assignee, '') then jsonb_build_array(jsonb_build_object('by', 'Automation', 'at', q2.ms, 'field', 'Assignee', 'from', coalesce(b.assignee, ''), 'to', coalesce(q2.pid, ''))) else '[]'::jsonb end) || (case when coalesce(q2.pid, '') is distinct from coalesce(b.reporter, '') then jsonb_build_array(jsonb_build_object('by', 'Automation', 'at', q2.ms, 'field', 'Reporter', 'from', coalesce((select x.name from wf_people x where x.id::text = b.reporter), nullif(b.reporter, ''), 'None'), 'to', coalesce(q2.pname, 'None'), 'toId', coalesce(q2.pid, ''))) else '[]'::jsonb end) || (case when q2.pid is null then jsonb_build_array(jsonb_build_object('by', 'Automation', 'at', q2.ms, 'field', 'note', 'text', case when q2.team_name is null then 'No team is set on this bid, so the assignee and reporter are unknown.' else 'Nobody on ' || q2.team_name || ' has the role ' || q2.role || ', so the assignee and reporter are unknown.' end)) else '[]'::jsonb end), updated_at = now() from q2 where b.id = q2.id and (coalesce(q2.pid, '') is distinct from coalesce(b.assignee, '') or coalesce(q2.pid, '') is distinct from coalesce(b.reporter, '')) returning b.id, q2.ms, q2.pid), ins as (insert into wf_notify (bid_id, through) select id::text, ms from upd on conflict (bid_id) do update set through = greatest(wf_notify.through, excluded.through) returning 1), rot as (update wf_teams t set rotation = coalesce(t.rotation, '{}'::jsonb) || jsonb_build_object(lower(l.role), l.pid) from (select distinct on (team_id, lower(role)) team_id, role, pid from q2 where pid is not null order by team_id, lower(role), num desc, id desc) l where t.id = l.team_id returning 1) select (select count(*) from q2) as copies_checked, (select count(*) from upd) as bids_changed, (select count(*) from q2 where pid is null) as unknown;
